package com.srenterprises.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.*; import org.springframework.beans.factory.annotation.*; import org.springframework.stereotype.*; import javax.crypto.*; import java.nio.charset.*; import java.util.*; import java.time.*;
@Service public class JwtService { private final SecretKey key; public JwtService(@Value("${app.jwt-secret}") String secret){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String issue(String email,String role){return Jwts.builder().subject(email).claim("role",role).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(8,java.time.temporal.ChronoUnit.HOURS))).signWith(key).compact();} public String email(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }
